export type IonName = keyof typeof GLYPHS;

/** `<Ion name="person-outline" size={18} />`, the app's `<Ionicons name size />`. */
export function Ion({ name, size = 18, ...rest }: { name: IonName; size?: number } & Omit<SVGProps<SVGSVGElement>, "name">) {
  return (
    <svg viewBox="0 0 512 512" width={size} height={size} fill="currentColor" aria-hidden focusable="false" {...rest}>
      <path d={GLYPHS[name]} />
    </svg>
  );
}
